const HIGH_COMBINING: &[(u32, u32)] = &[
    (0x10A01, 0x10A03),
    (0x10A05, 0x10A06),
    (0x10A0C, 0x10A0F),
    (0x10A38, 0x10A3A),
    (0x10A3F, 0x10A3F),
    (0x1D167, 0x1D169),
    (0x1D173, 0x1D182),
    (0x1D185, 0x1D18B),
    (0x1D1AA, 0x1D1AD),
    (0x1D242, 0x1D244),
    (0xE0001, 0xE0001),
    (0xE0020, 0xE007F),
    (0xE0100, 0xE01EF),
];

fn in_ranges(c: u32, table: &[(u32, u32)]) -> bool {
    table.binary_search_by(|&(low, high)| {
        if c < low {
            std::cmp::Ordering::Greater
        } else if c > high {
            std::cmp::Ordering::Less
        } else {
            std::cmp::Ordering::Equal
        }
    })
    .is_ok()
}

/// The number of cells `c` takes: 0 for control and combining characters, 2 for wide ones.
pub fn wcwidth(c: char) -> usize {
    let num = u32::from(c);
    if num < 32 {
        return 0;
    }
    if num < 127 {
        return 1;
    }
    if num < 65536 {
        return bmp_width(num);
    }
    if in_ranges(num, HIGH_COMBINING) {
        return 0;
    }
    if (0x20000..=0x2fffd).contains(&num) || (0x30000..=0x3fffd).contains(&num) {
        return 2;
    }
    1
}

fn bmp_width(num: u32) -> usize {
    if num == 0 {
        return 0;
    }
    if (0x7f..0xa0).contains(&num) {
        return 0;
    }
    // Combining wins over wide, as xterm applies it last.
    if in_ranges(num, BMP_COMBINING) {
        return 0;
    }
    if num == 0x303f {
        return 1;
    }
    let wide = (0x1100..0x1160).contains(&num)
        || num == 0x2329
        || num == 0x232a
        || (0x2e80..0xa4d0).contains(&num)
        || (0xac00..0xd7a4).contains(&num)
        || (0xf900..0xfb00).contains(&num)
        || (0xfe10..0xfe1a).contains(&num)
        || (0xfe30..0xfe70).contains(&num)
        || (0xff00..0xff61).contains(&num)
        || (0xffe0..0xffe7).contains(&num);
    if wide {
        2
    } else {
        1
    }
}
